function applyTechnologyBrand(value: string) {
  return value
    .replaceAll("Barmentech Formation", "Barmentech Technology")
    .replaceAll("public Formation website", "public Technology website")
    .replaceAll("current public Formation website", "current public Technology website");
}

export function getTechnologyLegalContent(locale: Locale, page: TechnologyLegalPage): TechnologyLegalContent {
  if (page === "privacy") return technologyPrivacyContent[locale];
  if (page === "terms") return technologyTermsContent[locale];
  if (page === "disclaimer") return technologyDisclaimerContent[locale];

  const content: FormationLegalContent = getFormationLegalContent(locale, page);
  return {
    ...content,
    eyebrow: locale === "en" ? "Barmentech Technology" : "Barmentech Tecnología",
    description: applyTechnologyBrand(content.description),
    sections: content.sections.map((section) => ({ ...section, body: section.body.map(applyTechnologyBrand) })),
  };
}

export function isTechnologyLegalPage(value: string): value is TechnologyLegalPage {
  return technologyLegalPages.has(value as TechnologyLegalPage);
}
